    {
        const float cosA = std::cos(angle);
        const float sinA = std::sin(angle);
        return Vector2{.x = v.x * cosA - v.y * sinA, .y = v.x * sinA + v.y * cosA};
    };
    const auto at = [&](float x, float y) -> Vector2
    { return Vector2Add(p, rotate(Vector2{.x = x * r, .y = y * r})); };
