    const float flicker = 0.65F + 0.35F * std::sin(static_cast<float>(GetTime()) * 28.0F);
    const Color flameOuter =
        ColorAlpha(Color{.r = 255, .g = 120, .b = 90, .a = 255}, 0.7F + 0.3F * flicker);
